<?php

use App\Models\Kelas;
use App\Models\PilketosHakPilih;
use App\Models\PilketosPeriode;
use App\Models\Siswa;
use Livewire\Attributes\Layout;
use Livewire\WithPagination;
use Livewire\Volt\Component;

new #[Layout('layouts.pilketos')] class extends Component {
    use WithPagination;
    public ?int $periodeId = null;
    public ?int $kelasId = null;
    public string $status = '';
    public string $search = '';
    public function mount(): void { $this->periodeId = PilketosPeriode::query()->latest('tahun')->value('id'); }
    public function updated($name): void { if (in_array($name, ['periodeId','kelasId','status','search'], true)) $this->resetPage(); }
    public function resetFilters(): void { $this->kelasId = null; $this->status = ''; $this->search = ''; $this->resetPage(); }
    public function with(): array { $periode = PilketosPeriode::find($this->periodeId); if (! $periode) return ['periodes'=>collect(),'kelas'=>collect(),'pemilih'=>collect(),'summary'=>[]]; $students = Siswa::query()->where('tahun',$periode->tahun)->selectRaw('nis, MAX(kelas_id) kelas_id')->groupBy('nis'); $q = PilketosHakPilih::query()->where('pilketos_hak_pilih.periode_id',$periode->id)->where('pilketos_hak_pilih.voter_type','siswa')->joinSub($students,'sp',fn($j)=>$j->on('pilketos_hak_pilih.nis','=','sp.nis'))->leftJoin('user_siswa','user_siswa.nis','=','pilketos_hak_pilih.nis')->leftJoin('kelas','kelas.id','=','sp.kelas_id')->select('pilketos_hak_pilih.*','user_siswa.name','kelas.tingkat','kelas.nama as nama_kelas')->when($this->kelasId,fn($q)=>$q->where('sp.kelas_id',$this->kelasId))->when($this->status,fn($q)=>$q->where('pilketos_hak_pilih.status',$this->status))->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('user_siswa.name','like',"%{$this->search}%")->orWhere('pilketos_hak_pilih.nis','like',"%{$this->search}%"))); return ['periodes'=>PilketosPeriode::latest('tahun')->get(),'kelas'=>Kelas::orderBy('tingkat')->orderBy('nama')->get(),'pemilih'=>$q->orderBy('user_siswa.name')->paginate(25),'summary'=>['total'=>(clone $q)->count(),'sudah'=>(clone $q)->where('pilketos_hak_pilih.status','sudah_memilih')->count(),'belum'=>(clone $q)->where('pilketos_hak_pilih.status','belum_memilih')->count()]]; }
}; ?>
<div><a wire:navigate href="{{ route('guru.dashboard') }}" class="font-bold text-emerald-700">← Dashboard</a><h1 class="mt-4 text-3xl font-black">Pemilih Siswa</h1><div class="mt-5 grid gap-3 rounded-2xl bg-white p-4 shadow md:grid-cols-5"><select wire:model.live="periodeId">@foreach($periodes as $item)<option value="{{ $item->id }}">{{ $item->tahun }}</option>@endforeach</select><select wire:model.live="kelasId"><option value="">Semua kelas</option>@foreach($kelas as $item)<option value="{{ $item->id }}">{{ $item->tingkat }} {{ $item->nama }}</option>@endforeach</select><select wire:model.live="status"><option value="">Semua status</option><option value="sudah_memilih">Sudah memilih</option><option value="belum_memilih">Belum memilih</option></select><input wire:model.live.debounce.300ms="search" placeholder="Cari nama atau NIS"><button wire:click="resetFilters" class="rounded-xl border px-3 font-bold">Reset</button></div><div class="mt-5 grid gap-3 sm:grid-cols-3">@foreach(['Total'=>$summary['total'] ?? 0,'Sudah'=>$summary['sudah'] ?? 0,'Belum'=>$summary['belum'] ?? 0] as $label=>$value)<article class="rounded-2xl bg-white p-4 shadow"><p>{{ $label }}</p><p class="text-3xl font-black">{{ $value }}</p></article>@endforeach</div><div wire:loading.delay class="mt-5"><x-skeleton variant="table" /></div><section wire:loading.remove class="mt-5 overflow-x-auto rounded-2xl bg-white shadow"><table class="min-w-full text-left text-sm"><thead class="sticky top-0 bg-slate-50"><tr><th class="p-3">Nama</th><th class="p-3">Kelas</th><th class="p-3">Status</th></tr></thead><tbody>@forelse($pemilih as $item)<tr class="border-t" wire:key="siswa-{{ $item->id }}"><td class="p-3">{{ $item->name }}</td><td class="p-3">{{ $item->tingkat }} {{ $item->nama_kelas }}</td><td class="p-3"><span class="rounded-full px-2 py-1 text-xs font-bold {{ $item->status === 'sudah_memilih' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800' }}">{{ str($item->status)->replace('_',' ')->title() }}</span></td></tr>@empty<tr><td colspan="3" class="p-8 text-center text-slate-500">Tidak ada pemilih untuk filter ini.</td></tr>@endforelse</tbody></table></section>{{ $pemilih instanceof \Illuminate\Contracts\Pagination\Paginator ? $pemilih->links() : '' }}</div>
